package org.researchdock.mobile;
import org.json.*;
import java.util.*;
/** Pure metadata rules; no network, model calls or file parsing. */
final class OriginalFiles {
 static final class Entry {final JSONObject item;final boolean source;Entry(JSONObject i,boolean s){item=i;source=s;}}
 static List<Entry> entries(JSONObject doc){ArrayList<Entry> result=new ArrayList<>();HashSet<String> managed=new HashSet<>();JSONArray source=doc.optJSONArray("attachments");if(source!=null)for(int n=0;n<source.length();n++){JSONObject item=source.optJSONObject(n);if(item==null)continue;result.add(new Entry(item,true));if(!item.optString("asset_id").isEmpty())managed.add(item.optString("asset_id"));}JSONArray assets=doc.optJSONArray("assets");if(assets!=null)for(int n=0;n<assets.length();n++){JSONObject a=assets.optJSONObject(n);if(a==null||managed.contains(a.optString("id")))continue;try{JSONObject item=new JSONObject().put("id",a.optString("id")).put("asset_id",a.optString("id")).put("name",a.optString("name")).put("type",a.optString("type")).put("status","ready").put("message","补充归档文件");result.add(new Entry(item,false));managed.add(a.optString("id"));}catch(JSONException ignored){}}return result;}
 static boolean matches(JSONObject doc,JSONObject item,String query,String type,String state,boolean cached){if(!type.isEmpty()&&!item.optString("type").equals(type))return false;String status=item.optString("status");if(state.equals("local")&&!cached||!state.isEmpty()&&!state.equals("local")&&!state.equals(status))return false;String q=query.trim().toLowerCase(Locale.ROOT);if(q.isEmpty()||LibraryViews.isCodeQuery(query.trim()))return true;String context=doc.optString("title")+" "+doc.optString("summary")+" "+doc.optString("companies")+" "+doc.optString("company_securities")+" "+doc.optString("industries");return item.optString("name").toLowerCase(Locale.ROOT).contains(q)||context.toLowerCase(Locale.ROOT).contains(q);}
 static JSONObject mergeCached(JSONObject cached,JSONObject catalog)throws JSONException{if(!cached.optString("document_id").equals(catalog.optString("document_id"))||cached.optInt("revision")<1||cached.optInt("revision")!=catalog.optInt("revision")||!cached.has("body"))return null;JSONObject merged=new JSONObject(catalog.toString());merged.put("body",cached.getString("body"));return merged;}
}
